/* Source-only spare-parts focus. Workbook records are never changed. */
(() => {
  'use strict';
  const BLUE='#24558f',TEAL='#328d92',PALE='#b4c6db',MUTED='#7890ac';
  const sumBy=(rows,key)=>rows.reduce((v,r)=>v+(Number(r[key])||0),0),safe=s=>esc(s),fmt=(v,d=1)=>num(v,d);
  const focus=()=>state.site==='all'?'S04':state.site;
  function metrics(siteId='S04'){
    if(siteId!=='all'&&!DATA.sites.some(s=>s.site_id===siteId))throw Error('Unknown site');
    const selected=rows=>rows.filter(r=>siteId==='all'||r.site_id===siteId),events=selected(DATA.events).filter(e=>e.event_type==='Unplanned'),affected=events.filter(e=>e.parts_wait_hours>0),assets=selected(DATA.assets),hse=selected(DATA.hse),open=hse.filter(h=>h.action_status==='Open'),site=DATA.sites.find(s=>s.site_id===siteId);
    const parts=sumBy(events,'parts_wait_hours'),total=sumBy(events,'stopped_hours');
    return {site_id:siteId,site_name:site?.site_name||'All sites',event_count:events.length,parts_affected_events:affected.length,parts_wait_hours:parts,unplanned_hours:total,parts_share_pct:total?parts/total*100:0,company_parts_wait_share_pct:sumBy(DATA.events.filter(e=>e.event_type==='Unplanned'),'parts_wait_hours')?parts/sumBy(DATA.events.filter(e=>e.event_type==='Unplanned'),'parts_wait_hours')*100:0,source_spare_fill_pct:site?.spare_fill_pct??null,avg_parts_wait_per_affected_event:affected.length?parts/affected.length:null,
      monthly:Array.from({length:12},(_,i)=>{const month='2025-'+String(i+1).padStart(2,'0'),rows=events.filter(e=>e.start_utc.startsWith(month));return {month,label:new Date(month+'-01T12:00:00Z').toLocaleDateString('en-US',{month:'short',timeZone:'UTC'}),parts_wait_hours:sumBy(rows,'parts_wait_hours'),affected_events:rows.filter(e=>e.parts_wait_hours>0).length};}),
      assets:assets.map(a=>{const rows=events.filter(e=>e.asset_id===a.asset_id);return {asset_id:a.asset_id,asset_type:a.asset_type,parts_wait_hours:sumBy(rows,'parts_wait_hours'),affected_events:rows.filter(e=>e.parts_wait_hours>0).length};}).sort((a,b)=>b.parts_wait_hours-a.parts_wait_hours),
      hse:{open_count:open.length,critical_open_count:open.filter(h=>h.potential_severity===5).length,severity:[5,4,3,2,1].map(severity=>({severity,count:open.filter(h=>h.potential_severity===severity).length})),critical_actions:open.filter(h=>h.potential_severity===5).map(h=>({id:h.hse_id,hazard:h.hazard,site_id:h.site_id,asset_id:h.asset_id,source_status:h.action_status}))}};
  }
  const allSites=()=>DATA.sites.map(s=>metrics(s.site_id)).sort((a,b)=>b.parts_wait_hours-a.parts_wait_hours);
  function comparison(siteId=focus()) {const selected=metrics(siteId),others=allSites().filter(s=>s.site_id!==siteId),hours=sumBy(others,'parts_wait_hours'),events=sumBy(others,'parts_affected_events');return {focus:selected,other_sites:others.length,other_site_mean_parts_wait_hours:hours/others.length,other_site_mean_affected_events:events/others.length,other_site_mean_source_spare_fill_pct:sumBy(others,'source_spare_fill_pct')/others.length,other_sites_combined_avg_wait_per_affected_event:events?hours/events:null,parts_wait_ratio_to_other_site_mean:hours?selected.parts_wait_hours/(hours/others.length):null};}
  function scenario(siteId=focus()){const m=metrics(siteId),rate=.60,saved=m.parts_wait_hours*rate;return {site_id:siteId,option:'O4',basis:'Full comparable operating year after implementation',source:'Solutions!S5; J5:K5',parts_wait_reduction:rate,baseline_parts_wait_hours:m.parts_wait_hours,saved_parts_wait_hours:saved,remaining_parts_wait_hours:m.parts_wait_hours-saved,baseline_unplanned_hours:m.unplanned_hours,remaining_unplanned_hours:m.unplanned_hours-saved,total_unplanned_reduction_pct:m.unplanned_hours?saved/m.unplanned_hours*100:0};}
  const svg=(body,w,h,title)=>`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${safe(title)}"><title>${safe(title)}</title>${body}</svg>`;
  function horizontal(rows,{small=false,unit='h',max=null,labels=true}={}){const w=small?280:400,h=small?77:172,L=small?48:68,R=small?48:58,T=small?4:14,B=small?6:23,maximum=max??Math.max(1,...rows.map(r=>r.value))*1.05,pw=w-L-R,gap=(h-T-B)/Math.max(1,rows.length),bar=Math.min(small?11:14,gap*.55);let out='';
    rows.forEach((r,i)=>{const y=T+i*gap+(gap-bar)/2,tip=r.name+': '+fmt(r.value,unit==='actions'?0:2)+' '+unit;out+=`<rect x="${L}" y="${y}" width="${pw}" height="${bar}" rx="3" fill="#edf2f7"/><rect x="${L}" y="${y}" width="${Math.max(0,r.value/maximum*pw)}" height="${bar}" rx="3" fill="${r.color||BLUE}" data-tooltip="${safe(tip)}"><title>${safe(tip)}</title></rect>`;if(labels)out+=`<text x="${L-9}" y="${y+bar/2+3.5}" text-anchor="end" font-size="${small?10:12}" fill="#66809e">${safe(r.name)}</text><text x="${w-R+9}" y="${y+bar/2+3.5}" font-size="${small?10:12}" fill="#385b82">${fmt(r.value,unit==='actions'?0:1)}</text>`;});if(!small)out+=`<text x="${L}" y="${h-3}" font-size="11" fill="#91a1b5">${unit==='h'?'Equipment-hours':unit==='actions'?'Source-open actions':safe(unit)}</text>`;return svg(out,w,h,rows.map(r=>r.name+': '+fmt(r.value,2)+' '+unit).join('; '));}
  function monthly(m,small=false){const w=small?280:400,h=small?77:172,L=small?5:38,R=small?5:12,T=small?6:14,B=small?16:25,max=Math.max(1,...m.monthly.map(x=>x.parts_wait_hours))*1.12,pw=w-L-R,ph=h-T-B,x=i=>L+i*pw/11,y=v=>T+ph-v/max*ph;let out='';
    if(!small)for(let n=0;n<=3;n++){const v=max*n/3,yy=y(v);out+=`<line x1="${L}" y1="${yy}" x2="${w-R}" y2="${yy}" stroke="#edf1f6"/><text x="${L-7}" y="${yy+3}" text-anchor="end" font-size="11" fill="#90a0b5">${fmt(v,0)}</text>`;}
    const pts=m.monthly.map((r,i)=>`${x(i)},${y(r.parts_wait_hours)}`).join(' ');out+=`<polygon points="${L},${T+ph} ${pts} ${w-R},${T+ph}" fill="#edf4fb"/><polyline points="${pts}" fill="none" stroke="${BLUE}" stroke-width="2" stroke-linejoin="round"/>`;
    m.monthly.forEach((r,i)=>{out+=`<circle cx="${x(i)}" cy="${y(r.parts_wait_hours)}" r="${small?2:3}" fill="${TEAL}" data-tooltip="${safe(r.label+': '+fmt(r.parts_wait_hours,2)+' equipment-hours')}"><title>${safe(r.label+' 2025: '+fmt(r.parts_wait_hours,2)+' parts-wait equipment-hours; '+r.affected_events+' affected events')}</title></circle>`;if(!small||[0,3,6,9,11].includes(i))out+=`<text x="${x(i)}" y="${h-5}" text-anchor="middle" font-size="${small?9:11}" fill="#8b9eb5">${r.label}</text>`;});if(!small)out+=`<text x="${L}" y="9" font-size="11" fill="#90a0b5">Equipment-hours</text>`;return svg(out,w,h,m.site_name+' monthly parts-wait equipment-hours, January–December 2025');}
  const source=text=>`<div class="af-source">${safe(text)}</div>`;
  const card=(title,body,action='')=>`<section class="af-panel"><div class="af-panel-head"><h2>${safe(title)}</h2>${action}</div><div class="af-panel-body">${body}</div></section>`;
  const dataButton=(kind,id)=>`<button class="af-link" data-af-table="${kind}" data-af-focus="${id}">View data</button>`;
  function otherSites(m,compact=false){const others=allSites().filter(s=>s.site_id!==m.site_id).sort((a,b)=>a.site_id==='S04'?-1:b.site_id==='S04'?1:b.parts_wait_hours-a.parts_wait_hours);return `<div class="af-other-sites ${compact?'compact':''}" aria-label="Other five sites, 2025 source context">${others.map(s=>`<button class="af-site-card ${s.site_id==='S04'?'priority':''}" data-af-site="${s.site_id}" aria-label="View ${safe(s.site_name)} parts evidence"><span>${safe(s.site_name)}</span><strong>${fmt(s.parts_wait_hours)} <small>h</small></strong><span class="af-site-meta">${fmt(s.source_spare_fill_pct,0)}% source fill · ${s.parts_affected_events} events</span></button>`).join('')}</div>`;}
  function renderPartsSummary(){const m=metrics(focus());return `<section class="af-summary" aria-label="Historical spare-parts priority"><div class="af-summary-focus"><div class="af-eyebrow">2025 workbook history</div><div class="af-summary-site">${safe(m.site_name)}</div><h2>${fmt(m.parts_wait_hours)} <span>hours waiting for parts</span></h2><div class="af-summary-metrics"><span title="Case planning assumption; not an inventory count"><strong>${fmt(m.source_spare_fill_pct,0)}%</strong> local fill · case baseline</span><span><strong>${m.parts_affected_events}</strong> affected events</span><span><strong>${fmt(m.parts_share_pct)}%</strong> of site downtime</span><span><strong>${fmt(m.company_parts_wait_share_pct)}%</strong> of company parts wait</span></div></div><div class="af-summary-chart"><h3>Monthly parts wait <span>h · 2025</span></h3>${monthly(m,true)}</div><div class="af-summary-chart"><h3>By asset <span>equipment-hours</span></h3>${horizontal(m.assets.map(a=>({name:a.asset_id,value:a.parts_wait_hours,color:a.parts_wait_hours===m.assets[0].parts_wait_hours?TEAL:PALE})),{small:true})}</div><div class="af-summary-bottom"><span>Other 5 sites · 2025 parts-wait hours</span>${otherSites(m,true)}</div></section>`;}
  function hero(m){const rank=allSites().findIndex(s=>s.site_id===m.site_id)+1,priority=m.site_id==='S04';return `<section class="af-hero"><div class="af-hero-copy"><div class="af-eyebrow">${priority?'Priority site':'Selected site'} · 2025 unplanned outages</div><h2>${safe(m.site_name)} <span>Parts availability</span></h2><p>${priority?'Highest parts-wait hours. Lowest source local fill.':'Rank '+rank+' of 6 for annual parts-wait hours.'}</p><div class="af-hero-tags"><span>${m.parts_affected_events} affected events${priority?' · most among sites':''}</span><span>${fmt(m.company_parts_wait_share_pct)}% of company parts wait</span></div></div><div class="af-hero-value"><span>Parts-wait hours</span><strong>${fmt(m.parts_wait_hours)} <small>h</small></strong><span>${fmt(m.parts_share_pct)}% of this site’s unplanned downtime</span></div><div class="af-hero-value af-fill"><span>Source local fill</span><strong>${fmt(m.source_spare_fill_pct,0)}<small>%</small></strong><span>Case baseline · not a stock count</span></div></section>`;}
  function renderDashboard(){const m=metrics(focus()),all=allSites(),c=comparison(m.site_id),s=scenario(m.site_id),priority=m.site_id==='S04';
    const compareTable=`<table class="af-comparison"><thead><tr><th>Historical measure</th><th>${safe(m.site_name)}</th><th>Other 5</th></tr></thead><tbody><tr><td>Annual parts wait</td><td>${fmt(m.parts_wait_hours)} h</td><td>${fmt(c.other_site_mean_parts_wait_hours)} h</td></tr><tr><td>Affected events</td><td>${m.parts_affected_events}</td><td>${fmt(c.other_site_mean_affected_events)}</td></tr><tr><td>Source local fill</td><td>${fmt(m.source_spare_fill_pct,0)}%</td><td>${fmt(c.other_site_mean_source_spare_fill_pct)}%</td></tr><tr><td>Wait / affected event</td><td>${fmt(m.avg_parts_wait_per_affected_event,2)} h</td><td>${fmt(c.other_sites_combined_avg_wait_per_affected_event,2)} h</td></tr></tbody></table>`;
    const critical=m.hse.critical_actions.map(h=>`<button class="af-action-link" data-af-hse="${safe(h.id)}" data-af-site-id="${safe(h.site_id)}"><strong>${safe(h.id)}</strong><span>${safe(h.hazard)}</span><span aria-hidden="true">→</span></button>`).join('');
    return `<div class="af-dashboard"><div class="af-context"><span>${safe(m.site_name)} focus${state.site==='all'?' · All-sites filter':''}</span><span>Comparisons: all 6 sites · Jan–Dec 2025</span></div>${hero(m)}<div class="af-sites-label"><span>Other sites</span><span>Parts-wait hours · source local fill</span></div>${otherSites(m)}<div class="af-chart-grid">${card('Where parts waits concentrate',horizontal(all.map(r=>({name:r.site_name,value:r.parts_wait_hours,color:r.site_id==='S04'?TEAL:r.site_id===m.site_id?BLUE:PALE})))+source('All six sites · Arroyo highlighted'),dataButton('ranking',m.site_id))}${card(m.site_name+' · monthly parts wait',monthly(m)+source('Unplanned events · historical pattern'),dataButton('monthly',m.site_id))}${card(m.site_name+' · asset breakdown',horizontal(m.assets.map(a=>({name:a.asset_id,value:a.parts_wait_hours,color:a.parts_wait_hours===m.assets[0].parts_wait_hours?TEAL:PALE})))+source('Source assets · equipment-hours'),dataButton('assets',m.site_id))}</div><div class="af-bottom-grid">${card('Put the site in context',compareTable+source('Other 5: unweighted mean of site totals. Wait/event uses combined hours ÷ events.')+`<div class="af-insight">${priority?'Arroyo has more affected events; mean wait per event is similar to other sites.':'Compare total exposure and per-event delay separately.'}</div>`)}${card('Potential HSE severity',`<div class="af-hse-top"><strong>${m.hse.open_count}<span>open</span></strong><strong>${m.hse.critical_open_count}<span>severity 5</span></strong><span>Source-open actions<br>Oct 1, 2026</span></div><div class="af-hse-bars">${m.hse.severity.map(h=>`<div><span>Severity ${h.severity}</span><div><i style="width:${Math.max(0,h.count/Math.max(1,...m.hse.severity.map(x=>x.count))*100)}%;background:${h.severity===5?'#9a627a':PALE}"></i></div><strong>${h.count}</strong></div>`).join('')}</div>${critical?`<div class="af-critical-actions">${critical}</div>`:'<div class="af-source">No source-open severity-5 actions at this site.</div>'}${source('Severity is potential consequence; no incident forecast.')}`)}${card('O4 · parts-wait scenario',`<div class="af-scenario-number"><strong>${fmt(s.saved_parts_wait_hours)} <small>h</small></strong><span>parts-wait hours potentially avoided</span></div><div class="af-scenario-bars">${[['Historical',s.baseline_parts_wait_hours,PALE],['O4 scenario',s.remaining_parts_wait_hours,TEAL]].map(([l,v,color])=>`<div><span>${l}</span><div><i style="width:${v/s.baseline_parts_wait_hours*100}%;background:${color}"></i></div><strong>${fmt(v)} h</strong></div>`).join('')}</div><div class="af-scenario-note"><strong>60% parts-wait reduction</strong><span>Full comparable year after implementation. Other stages and safety work unchanged.</span></div>${source('Modeled, not observed · Solutions!S5; J5:K5')}`,dataButton('scenario',m.site_id))}</div>${source('CaseQuest2026Dataset.xlsx · Assets / Events / HSE / Solutions · historical records and labeled scenario; no live feed or inventory balances inferred.')}</div>`;
  }
  window.ArroyoInsights=Object.freeze({renderDashboard,renderPartsSummary,metrics,comparison,scenario,allSites,focus});
})();
